-- C3: Supabase-first privacy authority for selection/reset (zero-Neon checklist C3/E3).
--
-- Slot 041000, assigned by the registry owner (layered-sessions-pipeline). The user/session index the authority
-- apply needs is a NON-TRANSACTIONAL post-apply operator job (the migrator wraps every migration in a transaction,
-- so CREATE INDEX CONCURRENTLY cannot live here): scripts/ops/c3-privacy-authority/ingest_privacy_authority_index.sql,
-- run only under an explicit apply OK. ingest_privacy_authority_activate refuses until that index is valid and ready.
-- Rollback (generated by scripts/sessions-function-boundary/lanes/privacy-authority.ts):
-- supabase/rollbacks/20261105041000_ingest_privacy_authority.down.sql. Dormant: no row in
-- sessions.ingest_privacy_authority means Neon is the authority and nothing below changes behaviour.
--
-- Before this change Neon is the privacy authority in every RHC mode, frozen-supabase included: the
-- Supabase mirror (20261105010000) only wraps Neon's begin/apply/complete. This adds a second,
-- default-off authority in which the Supabase head and the frozen privacy tables are written first
-- and are authoritative, and Neon is not written at all:
--
--   absent row  : Neon is the authority (today). Nothing below changes behaviour.
--   'fenced'    : owner-set. The legacy mirror begin (RHC mirror/frozen-supabase modes) refuses BEFORE
--                 Neon, so no new control reaches Neon; in-flight mirrored controls may still complete.
--                 The authority begin refuses too. Controls answer 503; uploads are unaffected.
--   'active'    : owner-set by ingest_privacy_authority_activate, which first makes the Supabase heads and
--                 frozen privacy byte-equal to a stable Neon snapshot (bound by a Neon-computed fingerprint)
--                 and proves every head equals the target's own control receipts. From then on only
--                 ingest_privacy_authority_begin/complete (RHC DELIVERY_CUSTODY_SOURCE_MODE=supabase-authority)
--                 can change heads or frozen privacy; every legacy writer (mirror begin/complete, the #260/#261
--                 parity/handoff tools, frozen-source-copy --copy) is refused by a statement guard.
--
-- The authority begin applies to the frozen tables exactly what Neon's set_session_uploads /
-- reset_uploaded_sessions would have applied to delivery_records / deleted_upload_sessions / session_resets,
-- in the same transaction as the head (Neon's set_session_uploads_cutover_v1 shape). The frozen witness
-- therefore keeps answering what the Neon witness would have answered, and the transcript eraser (E3)
-- reads ingest_frozen_source_deletions exactly where it read Neon's deleted_upload_sessions.
--
-- One-way after the first authority control: Neon's heads and privacy are then behind. ingest_privacy_authority_release
-- returns to Neon authority only while no authority control has happened (fingerprint unchanged since activation).
DO $authority_creator$
DECLARE me oid;
BEGIN
 SELECT oid INTO STRICT me FROM pg_roles WHERE rolname=current_user;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='sessions' AND c.relname IN('ingest_source_control_heads','ingest_frozen_source_deletions',
    'ingest_frozen_source_resets','ingest_frozen_source_records') AND c.relowner<>me)
  OR EXISTS(SELECT 1 FROM pg_proc WHERE oid IN('sessions.ingest_source_control_begin(jsonb)'::regprocedure,
    'sessions.ingest_source_control_complete(jsonb)'::regprocedure,'sessions.ingest_lazy_user(jsonb,text,jsonb)'::regprocedure,
    'sessions.ingest_lazy_begin(jsonb,text)'::regprocedure) AND proowner<>me) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: privacy authority requires original creator';END IF;
END $authority_creator$;

-- Neon's head carries the reset count a pending replay answers; the mirror head now carries it too.
ALTER TABLE sessions.ingest_source_control_heads ADD COLUMN deleted bigint CHECK(deleted IS NULL OR deleted>=0);

-- Neon's reset fences every session sessions.owned_uploaded_session_identities() returns: the user's
-- uploaded_support_identities (session_id NOT NULL) plus session ids recovered from null-session delete tombstones
-- through neighborhood_claims. The frozen delivery records alone do not cover that set, so the authority keeps an
-- exact copy of it (synced from Neon by scripts/privacy-authority-handoff.ts sync-owned, bound into activation by
-- a Neon-computed digest), and reset/selection maintain it exactly as Neon maintains uploaded_support_identities.
CREATE TABLE sessions.ingest_frozen_source_owned_sessions(
 org_id text NOT NULL,workspace_id text NOT NULL,user_id text NOT NULL,origin_id text NOT NULL,
 source text NOT NULL,session_id text NOT NULL,
 PRIMARY KEY(org_id,workspace_id,user_id,origin_id,source,session_id)
);
ALTER TABLE sessions.ingest_frozen_source_owned_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON sessions.ingest_frozen_source_owned_sessions
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

CREATE TABLE sessions.ingest_privacy_authority(
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 state text NOT NULL CHECK(state IN('fenced','active')),
 control_epoch text NOT NULL CHECK(control_epoch~'^[0-9a-f]{64}$'),
 neon_fingerprint_sha256 text CHECK(neon_fingerprint_sha256~'^[0-9a-f]{64}$'),
 fenced_at timestamptz NOT NULL DEFAULT clock_timestamp(),activated_at timestamptz,
 CHECK((state='fenced' AND neon_fingerprint_sha256 IS NULL AND activated_at IS NULL)
  OR (state='active' AND neon_fingerprint_sha256 IS NOT NULL AND activated_at IS NOT NULL))
);
ALTER TABLE sessions.ingest_privacy_authority ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON sessions.ingest_privacy_authority
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Every authority transition and every control that touches heads/frozen privacy serializes on this key:
-- begin/complete take it shared, fence/activate/release exclusive. Each check of the authority row runs
-- AFTER the lock (READ COMMITTED: a new snapshot per statement), so no begin can pass a check made
-- before a transition committed.
CREATE FUNCTION sessions.ingest_privacy_authority_lock(p_exclusive boolean) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,sessions,pg_temp AS $authority_lock$
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority requires read committed';END IF;
 IF p_exclusive THEN PERFORM pg_advisory_xact_lock(1919249529,96);
 ELSE PERFORM pg_advisory_xact_lock_shared(1919249529,96);END IF;
END $authority_lock$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_lock(boolean)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Statement guard: once 'active', only the authority functions (which set bulls96.privacy_authority_writer)
-- may write heads or frozen privacy/records. Statement level, so the 66M-row records table pays nothing per row.
CREATE FUNCTION sessions.ingest_privacy_authority_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $authority_guard$
BEGIN
 -- Every writer of a guarded table joins the authority lock (shared; activation and every transition hold it
 -- exclusively) BEFORE it checks the state, and the check runs after the lock (a new READ COMMITTED snapshot):
 --  * a writer already in flight holds activation off until it commits, so activation sees its effect;
 --  * a writer queued behind activation sees the committed 'active' state and refuses.
 -- Holding it to commit is what makes an uncommitted owned-copy page visible to activation (independent review P2).
 PERFORM pg_advisory_xact_lock_shared(1919249529,96);
 -- The owned-session copy is written only by sync-owned pages (READ COMMITTED) and the authority apply. Any other
 -- isolation could act on a snapshot older than a just-committed activation, so it is refused outright.
 IF TG_TABLE_NAME='ingest_frozen_source_owned_sessions' AND current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: owned sessions are written only in read committed';END IF;
 IF coalesce(current_setting('bulls96.privacy_authority_writer',true),'')<>'authority'
  AND EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority WHERE state='active') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority is supabase; legacy writer refused';END IF;
 RETURN NULL;
END $authority_guard$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_guard()
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;
CREATE TRIGGER ingest_privacy_authority_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON sessions.ingest_source_control_heads
 FOR EACH STATEMENT EXECUTE FUNCTION sessions.ingest_privacy_authority_guard();
CREATE TRIGGER ingest_privacy_authority_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON sessions.ingest_frozen_source_deletions
 FOR EACH STATEMENT EXECUTE FUNCTION sessions.ingest_privacy_authority_guard();
CREATE TRIGGER ingest_privacy_authority_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON sessions.ingest_frozen_source_resets
 FOR EACH STATEMENT EXECUTE FUNCTION sessions.ingest_privacy_authority_guard();
CREATE TRIGGER ingest_privacy_authority_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON sessions.ingest_frozen_source_records
 FOR EACH STATEMENT EXECUTE FUNCTION sessions.ingest_privacy_authority_guard();
CREATE TRIGGER ingest_privacy_authority_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON sessions.ingest_frozen_source_owned_sessions
 FOR EACH STATEMENT EXECUTE FUNCTION sessions.ingest_privacy_authority_guard();

-- The owned-session digest. NEON_OWNED_SESSIONS_DIGEST_SQL (src/migration/privacy-authority-handoff.ts) computes the
-- same text over Neon's owned identities; equal sets give equal bytes (every order COLLATE "C").
CREATE FUNCTION sessions.ingest_privacy_authority_owned_digest() RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,sessions,pg_temp AS $authority_owned_digest$
DECLARE n bigint;d text;
BEGIN
 SELECT count(*) INTO n FROM sessions.ingest_frozen_source_owned_sessions;
 IF n>5000000 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: owned sessions too large for a digest';END IF;
 SELECT encode(sha256(convert_to(coalesce(string_agg(jsonb_build_array(org_id,workspace_id,user_id,origin_id,source,session_id)::text,E'\n'
   ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",origin_id COLLATE "C",source COLLATE "C",session_id COLLATE "C"),''),'UTF8')),'hex')
  INTO d FROM sessions.ingest_frozen_source_owned_sessions;
 RETURN jsonb_build_object('rows',n::text,'sha256',d);
END $authority_owned_digest$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_owned_digest()
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- The privacy fingerprint. NEON_PRIVACY_FINGERPRINT_SQL (src/migration/privacy-authority-handoff.ts) runs the
-- same expression on Neon over delivery_cutover_control_heads / deleted_upload_sessions / session_resets;
-- both sides are PostgreSQL jsonb text with every order pinned to COLLATE "C", so equal state gives equal bytes.
CREATE FUNCTION sessions.ingest_privacy_authority_packet(p_heads jsonb,p_deletions jsonb,p_resets jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $authority_packet$
 SELECT encode(sha256(convert_to(jsonb_build_array('privacy-authority-v1',p_heads,p_deletions,p_resets)::text,'UTF8')),'hex')
$authority_packet$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_packet(jsonb,jsonb,jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

CREATE FUNCTION sessions.ingest_privacy_authority_state() RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,sessions,pg_temp AS $authority_state$
DECLARE h jsonb;d jsonb;r jsonb;nh bigint;nd bigint;nr bigint;np bigint;a sessions.ingest_privacy_authority%ROWTYPE;
BEGIN
 SELECT count(*),count(*) FILTER(WHERE pending) INTO nh,np FROM sessions.ingest_source_control_heads;
 SELECT count(*) INTO nd FROM sessions.ingest_frozen_source_deletions;
 SELECT count(*) INTO nr FROM sessions.ingest_frozen_source_resets;
 IF nh>100000 OR nd>200000 OR nr>100000 THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy state too large for a fingerprint';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_array(org_id,workspace_id,user_id,epoch,version::text,digest,kind,pending,deleted::text)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C"),'[]'::jsonb) INTO h FROM sessions.ingest_source_control_heads;
 SELECT coalesce(jsonb_agg(jsonb_build_array(org_id,workspace_id,user_id,origin_id,source,session_id)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",origin_id COLLATE "C",source COLLATE "C",session_id COLLATE "C"),'[]'::jsonb)
  INTO d FROM sessions.ingest_frozen_source_deletions;
 SELECT coalesce(jsonb_agg(jsonb_build_array(org_id,workspace_id,user_id,request_id,deleted::text)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",request_id COLLATE "C"),'[]'::jsonb)
  INTO r FROM sessions.ingest_frozen_source_resets;
 SELECT * INTO a FROM sessions.ingest_privacy_authority WHERE singleton;
 RETURN jsonb_build_object('authority',CASE WHEN a.state IS NULL THEN 'neon' ELSE a.state END,
  'fingerprintSha256',sessions.ingest_privacy_authority_packet(h,d,r),'heads',nh,'pendingHeads',np,'deletions',nd,'resets',nr,
  'activatedFingerprintSha256',a.neon_fingerprint_sha256);
END $authority_state$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_state()
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Owner: close the legacy (Neon-first) control path. Requires the sealed copy and the live policy epoch.
CREATE FUNCTION sessions.ingest_privacy_authority_fence(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,sessions,pg_temp AS $authority_fence$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;a sessions.ingest_privacy_authority%ROWTYPE;
BEGIN
 PERFORM sessions.ingest_exact_keys(p,ARRAY['controlEpoch']);
 PERFORM sessions.ingest_privacy_authority_lock(true);
 pol:=sessions.ingest_frozen_source_policy();
 IF p->>'controlEpoch' IS DISTINCT FROM pol.control_epoch THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority epoch mismatch';END IF;
 SELECT * INTO a FROM sessions.ingest_privacy_authority WHERE singleton FOR UPDATE;
 IF FOUND THEN
  IF a.state='fenced' AND a.control_epoch=pol.control_epoch THEN RETURN jsonb_build_object('state','fenced','changed',false);END IF;
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority already active';
 END IF;
 INSERT INTO sessions.ingest_privacy_authority(state,control_epoch) VALUES('fenced',pol.control_epoch);
 RETURN jsonb_build_object('state','fenced','changed',true);
END $authority_fence$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_fence(jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Owner: make Supabase exactly the given Neon snapshot, prove it against the target receipts, then activate.
-- p: {controlEpoch, neonFingerprintSha256, heads[{orgId,workspaceId,userId,epoch,version,digest,kind,pending,deleted,payload,privacyVersion}],
--     deletions[[org,ws,user,origin,source,session]], resets[[org,ws,user,request,deleted]]}
-- The snapshot must be the one Neon hashed (recomputed here), stable (the operator reads it twice >= settle apart
-- while fenced), and contain no pending head. Mirror heads may only be missing or older than Neon's; anything else refuses.
CREATE FUNCTION sessions.ingest_privacy_authority_activate(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,sessions,pg_temp AS $authority_activate$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;a sessions.ingest_privacy_authority%ROWTYPE;e jsonb;m sessions.ingest_source_control_heads%ROWTYPE;
 v_h jsonb;v_d jsonb;v_r jsonb;v_fp text;v_after jsonb;v_ins_d bigint;v_del_d bigint;v_ins_r bigint;v_del_r bigint;v_heads_written bigint:=0;v_last bigint;
BEGIN
 -- The writer marker the statement guard checks: transaction-local, set here (a function-level SET of a custom
 -- parameter needs superuser on PG15+) and cleared before every normal return. It is not a trust boundary.
 PERFORM set_config('bulls96.privacy_authority_writer','authority',true);
 PERFORM sessions.ingest_exact_keys(p,ARRAY['controlEpoch','neonFingerprintSha256','heads','deletions','resets','neonOwned']);
 PERFORM sessions.ingest_exact_keys(p->'neonOwned',ARRAY['rows','sha256']);
 PERFORM sessions.ingest_privacy_authority_lock(true);
 pol:=sessions.ingest_frozen_source_policy();
 SELECT * INTO a FROM sessions.ingest_privacy_authority WHERE singleton FOR UPDATE;
 IF NOT FOUND OR a.state<>'fenced' OR a.control_epoch<>pol.control_epoch OR p->>'controlEpoch' IS DISTINCT FROM pol.control_epoch THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority not fenced';END IF;
 -- The authority apply deletes a user's frozen records by session (selection) or by user (reset): without this
 -- index (built CONCURRENTLY by scripts/ops/c3-privacy-authority/ingest_privacy_authority_index.sql) each would scan a whole origin or org.
 IF NOT EXISTS(SELECT 1 FROM pg_index i WHERE i.indexrelid=to_regclass('sessions.ingest_frozen_source_records_user_session')
   AND i.indrelid='sessions.ingest_frozen_source_records'::regclass AND i.indisvalid AND i.indisready) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: user session index missing or invalid';END IF;
 IF jsonb_typeof(p->'heads')<>'array' OR jsonb_typeof(p->'deletions')<>'array' OR jsonb_typeof(p->'resets')<>'array'
  OR jsonb_array_length(p->'heads')>100000 OR jsonb_array_length(p->'deletions')>200000 OR jsonb_array_length(p->'resets')>100000 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid privacy snapshot';END IF;
 IF EXISTS(SELECT 1 FROM sessions.ingest_source_control_heads WHERE pending) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: mirror control pending';END IF;
 -- Validate and canonicalize the snapshot rows, then recompute the fingerprint Neon computed.
 CREATE TEMP TABLE pa_heads ON COMMIT DROP AS SELECT
   sessions.ingest_identifier(x->'orgId',false) AS org_id,sessions.ingest_identifier(x->'workspaceId',true) AS workspace_id,
   sessions.ingest_identifier(x->'userId',false) AS user_id,sessions.ingest_digest(x->'epoch') AS epoch,
   CASE WHEN jsonb_typeof(x->'version')='string' AND x->>'version'~'^[1-9][0-9]{0,18}$' THEN (x->>'version')::bigint END AS version,
   sessions.ingest_digest(x->'digest') AS digest,x->>'kind' AS kind,x->'pending' AS pending,
   CASE WHEN x->'deleted'='null'::jsonb THEN NULL WHEN jsonb_typeof(x->'deleted')='string' AND x->>'deleted'~'^(0|[1-9][0-9]{0,18})$' THEN (x->>'deleted')::bigint
    ELSE -1 END AS deleted,
   x->'payload' AS payload,
   CASE WHEN jsonb_typeof(x->'privacyVersion')='string' AND x->>'privacyVersion'~'^(0|[1-9][0-9]{0,18})$' THEN (x->>'privacyVersion')::bigint END AS privacy_version
  FROM jsonb_array_elements(p->'heads') q(x);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'heads') q(x) WHERE jsonb_typeof(x)<>'object' OR
   ARRAY(SELECT k FROM jsonb_object_keys(x) k ORDER BY k COLLATE "C") IS DISTINCT FROM
   ARRAY['deleted','digest','epoch','kind','orgId','payload','pending','privacyVersion','userId','version','workspaceId']::text[])
  OR EXISTS(SELECT 1 FROM pg_temp.pa_heads WHERE version IS NULL OR privacy_version IS NULL OR kind IS NULL OR kind NOT IN('selection','reset')
   OR pending IS DISTINCT FROM 'false'::jsonb OR deleted=-1 OR epoch<>pol.control_epoch OR payload IS NULL OR jsonb_typeof(payload)<>'object'
   OR encode(sha256(convert_to(jsonb_build_array('delivery-cutover-control-v1',epoch,org_id,workspace_id,user_id,kind,payload)::text,'UTF8')),'hex')<>digest)
  OR (SELECT count(*) FROM pg_temp.pa_heads)<>(SELECT count(DISTINCT (org_id,workspace_id,user_id)) FROM pg_temp.pa_heads) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid or pending neon head in snapshot';END IF;
 CREATE TEMP TABLE pa_del ON COMMIT DROP AS SELECT DISTINCT
   sessions.ingest_identifier(x->0,false) AS org_id,sessions.ingest_identifier(x->1,true) AS workspace_id,sessions.ingest_identifier(x->2,false) AS user_id,
   sessions.ingest_identifier(x->3,false) AS origin_id,sessions.ingest_identifier(x->4,false) AS source,sessions.ingest_identifier(x->5,false) AS session_id
  FROM jsonb_array_elements(p->'deletions') q(x);
 CREATE TEMP TABLE pa_res ON COMMIT DROP AS SELECT
   sessions.ingest_identifier(x->0,false) AS org_id,sessions.ingest_identifier(x->1,true) AS workspace_id,sessions.ingest_identifier(x->2,false) AS user_id,
   sessions.ingest_identifier(x->3,false) AS request_id,
   CASE WHEN jsonb_typeof(x->4)='string' AND x->>4~'^(0|[1-9][0-9]{0,18})$' THEN (x->>4)::bigint END AS deleted
  FROM jsonb_array_elements(p->'resets') q(x);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'deletions') q(x) WHERE jsonb_typeof(x)<>'array' OR jsonb_array_length(x)<>6)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'resets') q(x) WHERE jsonb_typeof(x)<>'array' OR jsonb_array_length(x)<>5)
  OR (SELECT count(*) FROM pg_temp.pa_del)<>jsonb_array_length(p->'deletions')
  OR EXISTS(SELECT 1 FROM pg_temp.pa_res WHERE deleted IS NULL)
  OR (SELECT count(*) FROM pg_temp.pa_res)<>(SELECT count(DISTINCT (org_id,workspace_id,user_id,request_id)) FROM pg_temp.pa_res) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid privacy snapshot';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_array(org_id,workspace_id,user_id,epoch,version::text,digest,kind,false,deleted::text)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C"),'[]'::jsonb) INTO v_h FROM pg_temp.pa_heads;
 SELECT coalesce(jsonb_agg(jsonb_build_array(org_id,workspace_id,user_id,origin_id,source,session_id)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",origin_id COLLATE "C",source COLLATE "C",session_id COLLATE "C"),'[]'::jsonb) INTO v_d FROM pg_temp.pa_del;
 SELECT coalesce(jsonb_agg(jsonb_build_array(org_id,workspace_id,user_id,request_id,deleted::text)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",request_id COLLATE "C"),'[]'::jsonb) INTO v_r FROM pg_temp.pa_res;
 v_fp:=sessions.ingest_privacy_authority_packet(v_h,v_d,v_r);
 IF v_fp IS DISTINCT FROM sessions.ingest_digest(p->'neonFingerprintSha256') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='frozen source: snapshot is not the neon fingerprint';END IF;
 -- Heads: a mirror head may be missing or strictly older (a qualified repair); never newer or a different same-version head.
 FOR m IN SELECT * FROM sessions.ingest_source_control_heads h WHERE NOT EXISTS(SELECT 1 FROM pg_temp.pa_heads n
   WHERE n.org_id=h.org_id AND n.workspace_id=h.workspace_id AND n.user_id=h.user_id) LOOP
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: mirror head without a neon head';
 END LOOP;
 FOR e IN SELECT to_jsonb(n) FROM pg_temp.pa_heads n LOOP
  SELECT * INTO m FROM sessions.ingest_source_control_heads WHERE org_id=e->>'org_id' AND workspace_id=e->>'workspace_id' AND user_id=e->>'user_id' FOR UPDATE;
  IF FOUND THEN
   IF m.epoch<>e->>'epoch' OR m.version>(e->>'version')::bigint
    OR (m.version=(e->>'version')::bigint AND (m.digest<>e->>'digest' OR m.kind<>e->>'kind')) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: mirror head diverges from neon';END IF;
   IF m.version<(e->>'version')::bigint OR m.deleted IS DISTINCT FROM (e->>'deleted')::bigint THEN
    UPDATE sessions.ingest_source_control_heads SET version=(e->>'version')::bigint,digest=e->>'digest',kind=e->>'kind',payload=e->'payload',
     pending=false,before_privacy=NULL,privacy_version=(e->>'privacy_version')::bigint,deleted=(e->>'deleted')::bigint,updated_at=clock_timestamp()
     WHERE org_id=m.org_id AND workspace_id=m.workspace_id AND user_id=m.user_id;
    v_heads_written:=v_heads_written+1;
   END IF;
  ELSE
   INSERT INTO sessions.ingest_source_control_heads(org_id,workspace_id,user_id,epoch,version,digest,kind,payload,pending,before_privacy,privacy_version,deleted)
    VALUES(e->>'org_id',e->>'workspace_id',e->>'user_id',e->>'epoch',(e->>'version')::bigint,e->>'digest',e->>'kind',e->'payload',false,NULL,
     (e->>'privacy_version')::bigint,(e->>'deleted')::bigint);
   v_heads_written:=v_heads_written+1;
  END IF;
 END LOOP;
 -- The target applied every Neon control through the mandatory ingest fence: its receipts must end exactly at each head.
 IF EXISTS(SELECT 1 FROM pg_temp.pa_heads n WHERE (SELECT max(r.version) FROM sessions.ingest_control_receipts r WHERE r.org_id=n.org_id
    AND r.workspace_id=n.workspace_id AND r.user_id=n.user_id AND r.epoch=n.epoch) IS DISTINCT FROM n.version
   OR NOT EXISTS(SELECT 1 FROM sessions.ingest_control_receipts r WHERE r.org_id=n.org_id AND r.workspace_id=n.workspace_id
    AND r.user_id=n.user_id AND r.epoch=n.epoch AND r.version=n.version AND r.digest=n.digest AND r.kind=n.kind))
  OR EXISTS(SELECT 1 FROM sessions.ingest_control_receipts r WHERE r.epoch=pol.control_epoch AND NOT EXISTS(SELECT 1 FROM pg_temp.pa_heads n
    WHERE n.org_id=r.org_id AND n.workspace_id=r.workspace_id AND n.user_id=r.user_id)) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: neon heads do not match the target control receipts';END IF;
 -- Privacy: exactly the snapshot.
 WITH x AS(DELETE FROM sessions.ingest_frozen_source_deletions d WHERE NOT EXISTS(SELECT 1 FROM pg_temp.pa_del n WHERE (n.org_id,n.workspace_id,n.user_id,n.origin_id,n.source,n.session_id)
   =(d.org_id,d.workspace_id,d.user_id,d.origin_id,d.source,d.session_id)) RETURNING 1) SELECT count(*) INTO v_del_d FROM x;
 WITH x AS(INSERT INTO sessions.ingest_frozen_source_deletions SELECT * FROM pg_temp.pa_del ON CONFLICT DO NOTHING RETURNING 1) SELECT count(*) INTO v_ins_d FROM x;
 WITH x AS(DELETE FROM sessions.ingest_frozen_source_resets d WHERE NOT EXISTS(SELECT 1 FROM pg_temp.pa_res n WHERE (n.org_id,n.workspace_id,n.user_id,n.request_id,n.deleted)
   =(d.org_id,d.workspace_id,d.user_id,d.request_id,d.deleted)) RETURNING 1) SELECT count(*) INTO v_del_r FROM x;
 WITH x AS(INSERT INTO sessions.ingest_frozen_source_resets SELECT * FROM pg_temp.pa_res ON CONFLICT DO NOTHING RETURNING 1) SELECT count(*) INTO v_ins_r FROM x;
 -- Reset coverage: the owned-session copy must be exactly Neon's owned identities (synced while fenced).
 IF sessions.ingest_privacy_authority_owned_digest() IS DISTINCT FROM jsonb_build_object('rows',p#>>'{neonOwned,rows}','sha256',p#>>'{neonOwned,sha256}') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: owned sessions differ from neon; sync-owned first';END IF;
 v_after:=sessions.ingest_privacy_authority_state();
 IF v_after->>'fingerprintSha256' IS DISTINCT FROM v_fp THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: activation did not reach the neon fingerprint';END IF;
 UPDATE sessions.ingest_privacy_authority SET state='active',neon_fingerprint_sha256=v_fp,activated_at=clock_timestamp() WHERE singleton;
 PERFORM set_config('bulls96.privacy_authority_writer','',true);
 RETURN jsonb_build_object('state','active','fingerprintSha256',v_fp,'headsWritten',v_heads_written,
  'deletionsInserted',v_ins_d,'deletionsRemoved',v_del_d,'resetsInserted',v_ins_r,'resetsRemoved',v_del_r);
END $authority_activate$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_activate(jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Owner: return to Neon authority. From 'fenced' always; from 'active' only while nothing changed since activation
-- (Neon is then still exactly equal). After the first authority control this refuses: the switch is one-way.
CREATE FUNCTION sessions.ingest_privacy_authority_release(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,sessions,pg_temp AS $authority_release$
DECLARE a sessions.ingest_privacy_authority%ROWTYPE;s jsonb;
BEGIN
 PERFORM sessions.ingest_exact_keys(p,ARRAY['controlEpoch']);
 PERFORM sessions.ingest_privacy_authority_lock(true);
 SELECT * INTO a FROM sessions.ingest_privacy_authority WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('authority','neon','changed',false);END IF;
 IF a.control_epoch IS DISTINCT FROM p->>'controlEpoch' THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority epoch mismatch';END IF;
 IF a.state='active' THEN
  s:=sessions.ingest_privacy_authority_state();
  IF s->>'fingerprintSha256' IS DISTINCT FROM a.neon_fingerprint_sha256 OR (s->>'pendingHeads')::bigint<>0 THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: supabase authority diverged from neon; release refused';END IF;
 END IF;
 DELETE FROM sessions.ingest_privacy_authority WHERE singleton;
 RETURN jsonb_build_object('authority','neon','changed',true,'from',a.state);
END $authority_release$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_release(jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Derived caches that can hold text of a deleted session. Neon's set_session_uploads deletes the workspace's
-- daily_digests (0074) when the user had a copy; the Supabase replacement is sessions.daily_digest_narratives,
-- purged by sessions.purge_daily_digest_narratives (migration 20261105045000, lane F4, which lands AFTER this one).
-- So the call is guarded: when 045000 is not applied the function does not exist and there is no cache to purge.
-- Conservative: every disable and every reset purges the workspace's narratives (a cache: it regenerates).
-- Same transaction as the head and the frozen privacy writes (045000's contract for C3).
CREATE FUNCTION sessions.ingest_privacy_authority_purge_derived(p_org text,p_ws text) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,sessions,pg_temp AS $authority_purge_derived$
BEGIN
 -- Guarded, but fail-closed: a no-op only while 045000 is entirely absent. Once ANY sign of it exists (its table or
 -- any overload of the purge), the exact (text,text) signature must exist, or the reset/disable aborts (never skips).
 IF to_regprocedure('sessions.purge_daily_digest_narratives(text,text)') IS NOT NULL THEN
  EXECUTE 'SELECT sessions.purge_daily_digest_narratives($1,$2)' USING p_org,p_ws;
 ELSIF to_regclass('sessions.daily_digest_narratives') IS NOT NULL OR EXISTS(SELECT 1 FROM pg_proc
   WHERE pronamespace='sessions'::regnamespace AND proname='purge_daily_digest_narratives') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: digest narrative purge ABI mismatch';
 END IF;
END $authority_purge_derived$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_purge_derived(text,text)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Neon's set_session_uploads / reset_uploaded_sessions, over the frozen copy. Called only inside the authority begin.
CREATE FUNCTION sessions.ingest_privacy_authority_apply(p_org text,p_ws text,p_user text,p_kind text,p_payload jsonb) RETURNS bigint
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,sessions,pg_temp AS $authority_apply$
DECLARE v_origin text;v_enabled boolean;item jsonb;v_total bigint;v_request text;v_analysis boolean;
BEGIN
 IF coalesce(current_setting('bulls96.privacy_authority_writer',true),'')<>'authority' THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='frozen source: authority apply outside the authority begin';END IF;
 -- The analysis purge ABI (046000, #292 b608ea3b), checked BEFORE any change. A no-op only while 046000 is entirely
 -- absent; once ANY sign of it exists (its jobs table or any purge_session_analysis_for_owned overload), BOTH exact
 -- workspace-scoped signatures must exist, or this reset/disable aborts (fail closed: it never silently skips).
 v_analysis:=to_regprocedure('sessions.purge_session_analysis_for_owned(text,text,text)') IS NOT NULL
  AND to_regprocedure('sessions.purge_session_analysis_for_owned(text,text,text,jsonb)') IS NOT NULL;
 IF NOT v_analysis AND (to_regclass('sessions.session_analysis_jobs_v2') IS NOT NULL OR EXISTS(SELECT 1 FROM pg_proc
   WHERE pronamespace='sessions'::regnamespace AND proname='purge_session_analysis_for_owned')) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: analysis purge ABI mismatch';END IF;
 IF p_kind='selection' THEN
  v_origin:=p_payload->>'origin_id';v_enabled:=(p_payload->>'enabled')::boolean;
  -- SP v2 analysis of exactly the disabled sessions in THIS workspace (046000's session-scoped form), BEFORE their owned/frozen rows
  -- are removed below (it reads them). v_analysis: the fail-closed ABI check above.
  IF NOT v_enabled AND v_analysis THEN
   EXECUTE 'SELECT sessions.purge_session_analysis_for_owned($1,$2,$3,$4)' USING p_org,p_ws,p_user,p_payload->'sessions';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'sessions') LOOP
   IF v_enabled THEN
    DELETE FROM sessions.ingest_frozen_source_deletions WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user
     AND origin_id=v_origin AND source=item->>'source' AND session_id=item->>'session_id';
   ELSE
    INSERT INTO sessions.ingest_frozen_source_deletions VALUES(p_org,p_ws,p_user,v_origin,item->>'source',item->>'session_id') ON CONFLICT DO NOTHING;
    DELETE FROM sessions.ingest_frozen_source_records WHERE org_id=p_org AND workspace_id=p_ws AND origin_id=v_origin AND user_id=p_user
     AND source=item->>'source' AND session_id=item->>'session_id';
    -- Neon's disable deletes the uploaded_support_identities of the session: so does the owned copy.
    DELETE FROM sessions.ingest_frozen_source_owned_sessions WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user
     AND origin_id=v_origin AND source=item->>'source' AND session_id=item->>'session_id';
   END IF;
  END LOOP;
  IF NOT v_enabled THEN PERFORM sessions.ingest_privacy_authority_purge_derived(p_org,p_ws);END IF;
  RETURN NULL;
 END IF;
 v_request:=p_payload->>'request_id';
 SELECT deleted INTO v_total FROM sessions.ingest_frozen_source_resets WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user AND request_id=v_request;
 IF FOUND THEN RETURN v_total;END IF;
 -- Owned sessions: Neon's owned_uploaded_session_identities (the exact owned copy, synced and digest-bound at
 -- activation) UNION the user's frozen delivery records with a session (a superset, never narrower than Neon).
 -- The count is Neon's: distinct (source, session_id) of the owned identities; the union only adds fences.
 CREATE TEMP TABLE pa_owned ON COMMIT DROP AS
  SELECT origin_id,source,session_id FROM sessions.ingest_frozen_source_owned_sessions WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user
  UNION
  SELECT origin_id,source,session_id FROM sessions.ingest_frozen_source_records WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user AND session_id IS NOT NULL;
 SELECT count(*) INTO v_total FROM(SELECT DISTINCT source,session_id FROM sessions.ingest_frozen_source_owned_sessions
  WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user)s;
 INSERT INTO sessions.ingest_frozen_source_deletions
  SELECT p_org,p_ws,p_user,o.origin_id,o.source,o.session_id FROM pg_temp.pa_owned o ON CONFLICT DO NOTHING;
 -- SP v2 analysis of Neon-era sessions (046000) in THIS workspace is keyed by the user's owned set, so it is purged BEFORE that set is
 -- emptied below. v_analysis: the fail-closed ABI check above.
 IF v_analysis THEN
  EXECUTE 'SELECT sessions.purge_session_analysis_for_owned($1,$2,$3)' USING p_org,p_ws,p_user;
 END IF;
 DELETE FROM sessions.ingest_frozen_source_records WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user AND session_id IS NOT NULL;
 DELETE FROM sessions.ingest_frozen_source_owned_sessions WHERE org_id=p_org AND workspace_id=p_ws AND user_id=p_user;
 DROP TABLE pg_temp.pa_owned;
 PERFORM sessions.ingest_privacy_authority_purge_derived(p_org,p_ws);
 INSERT INTO sessions.ingest_frozen_source_resets VALUES(p_org,p_ws,p_user,v_request,v_total);
 RETURN v_total;
END $authority_apply$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_apply(text,text,text,text,jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;

-- Supabase-first begin: Neon's begin_delivery_cutover_control_v1 + set_session_uploads_cutover_v1 /
-- reset_uploaded_sessions_cutover_v1, with Supabase as the authority. Same digest, version, PRE and
-- pending rules as Neon and the mirror, so the unchanged ingest fence accepts the control unchanged.
CREATE FUNCTION sessions.ingest_privacy_authority_begin(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $authority_begin$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;h sessions.ingest_source_control_heads%ROWTYPE;
 v_org text;v_ws text;v_user text;v_kind text;v_epoch text;v_payload jsonb;d text;fresh boolean;v_deleted bigint;s jsonb;
BEGIN
 -- The writer marker the statement guard checks: transaction-local, set here (a function-level SET of a custom
 -- parameter needs superuser on PG15+) and cleared before every normal return. It is not a trust boundary.
 PERFORM set_config('bulls96.privacy_authority_writer','authority',true);
 PERFORM sessions.ingest_exact_keys(p,ARRAY['epoch','tenant','kind','payload']);
 PERFORM sessions.ingest_exact_keys(p->'tenant',ARRAY['orgId','workspaceId','userId']);
 v_org:=sessions.ingest_identifier(p#>'{tenant,orgId}',false);v_ws:=sessions.ingest_identifier(p#>'{tenant,workspaceId}',true);
 v_user:=sessions.ingest_identifier(p#>'{tenant,userId}',false);v_kind:=p->>'kind';v_epoch:=p->>'epoch';v_payload:=p->'payload';
 IF v_kind IS NULL OR v_kind NOT IN('selection','reset') OR jsonb_typeof(v_payload) IS DISTINCT FROM 'object' OR octet_length(v_payload::text)>2113536 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid control';END IF;
 IF v_kind='selection' THEN
  PERFORM sessions.ingest_exact_keys(v_payload,ARRAY['origin_id','sessions','enabled']);
  PERFORM sessions.ingest_identifier(v_payload->'origin_id',false);
  IF jsonb_typeof(v_payload->'enabled') IS DISTINCT FROM 'boolean' OR jsonb_typeof(v_payload->'sessions') IS DISTINCT FROM 'array'
   OR jsonb_array_length(v_payload->'sessions') NOT BETWEEN 1 AND 2048 THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid selection';END IF;
  FOR s IN SELECT value FROM jsonb_array_elements(v_payload->'sessions') LOOP
   PERFORM sessions.ingest_exact_keys(s,ARRAY['source','session_id']);
   PERFORM sessions.ingest_identifier(s->'source',false);PERFORM sessions.ingest_identifier(s->'session_id',false);
  END LOOP;
 ELSE
  PERFORM sessions.ingest_exact_keys(v_payload,ARRAY['request_id']);PERFORM sessions.ingest_identifier(v_payload->'request_id',false);
 END IF;
 PERFORM sessions.ingest_privacy_authority_lock(false);
 pol:=sessions.ingest_frozen_source_policy();
 IF NOT EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority WHERE state='active' AND control_epoch=pol.control_epoch) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: supabase privacy authority not active';END IF;
 IF v_epoch IS DISTINCT FROM pol.control_epoch THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control epoch';END IF;
 d:=encode(sha256(convert_to(jsonb_build_array('delivery-cutover-control-v1',v_epoch,v_org,v_ws,v_user,v_kind,v_payload)::text,'UTF8')),'hex');
 INSERT INTO sessions.ingest_source_control_heads(org_id,workspace_id,user_id,epoch,version,digest,kind,payload,pending)
  VALUES(v_org,v_ws,v_user,v_epoch,1,d,v_kind,v_payload,true) ON CONFLICT DO NOTHING RETURNING true INTO fresh;
 SELECT * INTO STRICT h FROM sessions.ingest_source_control_heads WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user FOR UPDATE;
 IF coalesce(fresh,false) THEN
  -- PRE before the apply below can change it (Neon persists PRE before selection/reset create fences).
  UPDATE sessions.ingest_source_control_heads SET before_privacy=sessions.ingest_frozen_source_privacy(v_org,v_ws,v_user),privacy_version=0
   WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user RETURNING * INTO h;
 END IF;
 IF h.epoch IS DISTINCT FROM v_epoch THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control epoch';END IF;
 IF NOT coalesce(fresh,false) THEN
  IF h.pending THEN
   IF h.digest IS DISTINCT FROM d OR h.kind IS DISTINCT FROM v_kind THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: control pending';END IF;
   PERFORM set_config('bulls96.privacy_authority_writer','',true);
   RETURN jsonb_build_object('epoch',h.epoch,'version',h.version::text,'digest',h.digest,'kind',h.kind,'pending',true,
    'deleted',h.deleted::text,'apply',false);
  END IF;
  IF h.version=9223372036854775807 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: control version exhausted';END IF;
  UPDATE sessions.ingest_source_control_heads SET version=h.version+1,digest=d,kind=v_kind,payload=v_payload,pending=true,
   before_privacy=NULL,privacy_version=h.version,deleted=NULL,updated_at=clock_timestamp()
   WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user RETURNING * INTO h;
 END IF;
 v_deleted:=sessions.ingest_privacy_authority_apply(v_org,v_ws,v_user,v_kind,v_payload);
 IF v_kind='reset' THEN
  UPDATE sessions.ingest_source_control_heads SET deleted=v_deleted WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user;
 END IF;
 PERFORM set_config('bulls96.privacy_authority_writer','',true);
 RETURN jsonb_build_object('epoch',h.epoch,'version',h.version::text,'digest',h.digest,'kind',h.kind,'pending',true,
  'deleted',v_deleted::text,'apply',true);
END $authority_begin$;

-- Supabase-first completion, after the ingest fence acknowledged the same {version,digest}.
CREATE FUNCTION sessions.ingest_privacy_authority_complete(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $authority_complete$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;h sessions.ingest_source_control_heads%ROWTYPE;
 v_org text;v_ws text;v_user text;v_version bigint;v_outcome text;
BEGIN
 -- The writer marker the statement guard checks: transaction-local, set here (a function-level SET of a custom
 -- parameter needs superuser on PG15+) and cleared before every normal return. It is not a trust boundary.
 PERFORM set_config('bulls96.privacy_authority_writer','authority',true);
 PERFORM sessions.ingest_exact_keys(p,ARRAY['epoch','tenant','version','digest','kind','outcome']);
 PERFORM sessions.ingest_exact_keys(p->'tenant',ARRAY['orgId','workspaceId','userId']);
 v_org:=sessions.ingest_identifier(p#>'{tenant,orgId}',false);v_ws:=sessions.ingest_identifier(p#>'{tenant,workspaceId}',true);
 v_user:=sessions.ingest_identifier(p#>'{tenant,userId}',false);v_outcome:=p->>'outcome';
 IF jsonb_typeof(p->'version') IS DISTINCT FROM 'string' OR p->>'version'!~'^[1-9][0-9]{0,18}$' THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid control';END IF;
 v_version:=(p->>'version')::bigint;
 PERFORM sessions.ingest_privacy_authority_lock(false);
 pol:=sessions.ingest_frozen_source_policy();
 IF NOT EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority WHERE state='active' AND control_epoch=pol.control_epoch) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: supabase privacy authority not active';END IF;
 IF p->>'epoch' IS DISTINCT FROM pol.control_epoch OR v_outcome IS NULL OR v_outcome NOT IN('applied','replay','stale') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: control held';END IF;
 SELECT * INTO STRICT h FROM sessions.ingest_source_control_heads WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user FOR UPDATE;
 IF h.epoch IS DISTINCT FROM p->>'epoch' OR v_version>h.version THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control';END IF;
 -- A later head exists only after this intent completed; never clear the newer pending one.
 IF v_version<h.version THEN PERFORM set_config('bulls96.privacy_authority_writer','',true);RETURN jsonb_build_object('completed',true,'superseded',true);END IF;
 IF v_outcome NOT IN('applied','replay') OR h.digest IS DISTINCT FROM p->>'digest' OR h.kind IS DISTINCT FROM p->>'kind' THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control';END IF;
 UPDATE sessions.ingest_source_control_heads SET pending=false,updated_at=clock_timestamp()
  WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user;
 -- Buffered (staged, not yet published) copies: the ordered fence has now written the target's upload_deletions and
 -- reset epoch, so the buffered GC will redact them (ingest_buffer_gc_ordinals keeps nothing fenced) and remove their
 -- prior versions. Move this user's stages to the head of the GC queue, so they are examined next rather than after
 -- the whole round-robin (here, not at begin: the fence must have landed first, or a healthy check would re-queue them).
 UPDATE sessions.ingest_stage_intents SET gc_checked_at='-infinity'
  WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user AND cleanup_state<>'redacted'
   AND (h.kind='reset' OR (h.payload->>'enabled')='false' AND origin_id=h.payload->>'origin_id');
 PERFORM set_config('bulls96.privacy_authority_writer','',true);
 RETURN jsonb_build_object('completed',true,'superseded',false);
END $authority_complete$;
REVOKE ALL ON FUNCTION sessions.ingest_privacy_authority_begin(jsonb),sessions.ingest_privacy_authority_complete(jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest_seeder;
GRANT EXECUTE ON FUNCTION sessions.ingest_privacy_authority_begin(jsonb),sessions.ingest_privacy_authority_complete(jsonb) TO bulls96_session_ingest;

-- The legacy (Neon-first) mirror begin, unchanged except that it refuses as soon as the authority leaves Neon.
-- RHC calls it BEFORE Neon, so a refusal leaves Neon untouched (the H-2 straggler cannot create a divergent head).
CREATE OR REPLACE FUNCTION sessions.ingest_source_control_begin(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $control_begin$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;h sessions.ingest_source_control_heads%ROWTYPE;
 v_org text;v_ws text;v_user text;v_kind text;v_epoch text;d text;fresh boolean;
BEGIN
 PERFORM sessions.ingest_exact_keys(p,ARRAY['epoch','tenant','kind','payload']);
 PERFORM sessions.ingest_exact_keys(p->'tenant',ARRAY['orgId','workspaceId','userId']);
 v_org:=sessions.ingest_identifier(p#>'{tenant,orgId}',false);v_ws:=sessions.ingest_identifier(p#>'{tenant,workspaceId}',true);
 v_user:=sessions.ingest_identifier(p#>'{tenant,userId}',false);v_kind:=p->>'kind';v_epoch:=p->>'epoch';
 IF v_kind IS NULL OR v_kind NOT IN('selection','reset') OR p->'payload' IS NULL OR jsonb_typeof(p->'payload')='null'
  OR octet_length((p->'payload')::text)>2113536 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid control';END IF;
 PERFORM sessions.ingest_privacy_authority_lock(false);
 IF EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority moved; legacy control refused';END IF;
 pol:=sessions.ingest_frozen_source_policy();
 IF v_epoch IS DISTINCT FROM pol.control_epoch THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control epoch';END IF;
 d:=encode(sha256(convert_to(jsonb_build_array('delivery-cutover-control-v1',v_epoch,v_org,v_ws,v_user,v_kind,p->'payload')::text,'UTF8')),'hex');
 INSERT INTO sessions.ingest_source_control_heads(org_id,workspace_id,user_id,epoch,version,digest,kind,payload,pending)
  VALUES(v_org,v_ws,v_user,v_epoch,1,d,v_kind,p->'payload',true) ON CONFLICT DO NOTHING RETURNING true INTO fresh;
 SELECT * INTO STRICT h FROM sessions.ingest_source_control_heads WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user FOR UPDATE;
 IF coalesce(fresh,false) THEN
  UPDATE sessions.ingest_source_control_heads SET before_privacy=sessions.ingest_frozen_source_privacy(v_org,v_ws,v_user),privacy_version=0
   WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user RETURNING * INTO h;
 END IF;
 IF h.epoch IS DISTINCT FROM v_epoch THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control epoch';END IF;
 IF NOT coalesce(fresh,false) THEN
  IF h.pending THEN
   IF h.digest IS DISTINCT FROM d OR h.kind IS DISTINCT FROM v_kind THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: control pending';END IF;
   RETURN jsonb_build_object('epoch',h.epoch,'version',h.version::text,'digest',h.digest,'kind',h.kind,'pending',true,'apply',false);
  END IF;
  IF h.version=9223372036854775807 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: control version exhausted';END IF;
  UPDATE sessions.ingest_source_control_heads SET version=h.version+1,digest=d,kind=v_kind,payload=p->'payload',pending=true,
   before_privacy=NULL,privacy_version=h.version,updated_at=clock_timestamp()
   WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user RETURNING * INTO h;
 END IF;
 RETURN jsonb_build_object('epoch',h.epoch,'version',h.version::text,'digest',h.digest,'kind',h.kind,'pending',true,'apply',true);
END $control_begin$;

-- The legacy mirror completion takes the same shared lock, so it serializes with activation (which requires
-- no pending head). While fenced it still completes in-flight stragglers; once active it refuses.
CREATE OR REPLACE FUNCTION sessions.ingest_source_control_complete(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $control_complete$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;h sessions.ingest_source_control_heads%ROWTYPE;
 v_org text;v_ws text;v_user text;v_version bigint;v_outcome text;
BEGIN
 PERFORM sessions.ingest_exact_keys(p,ARRAY['epoch','tenant','version','digest','kind','outcome']);
 PERFORM sessions.ingest_exact_keys(p->'tenant',ARRAY['orgId','workspaceId','userId']);
 v_org:=sessions.ingest_identifier(p#>'{tenant,orgId}',false);v_ws:=sessions.ingest_identifier(p#>'{tenant,workspaceId}',true);
 v_user:=sessions.ingest_identifier(p#>'{tenant,userId}',false);v_outcome:=p->>'outcome';
 IF p->>'version'!~'^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid control';END IF;
 v_version:=(p->>'version')::bigint;
 PERFORM sessions.ingest_privacy_authority_lock(false);
 -- Explicit, not only the statement guard: the guard's session setting is not a trust boundary.
 IF EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority WHERE state='active') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: privacy authority moved; legacy control refused';END IF;
 pol:=sessions.ingest_frozen_source_policy();
 IF p->>'epoch' IS DISTINCT FROM pol.control_epoch OR v_outcome IS NULL OR v_outcome NOT IN('applied','replay','stale') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: control held';END IF;
 SELECT * INTO STRICT h FROM sessions.ingest_source_control_heads WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user FOR UPDATE;
 IF h.epoch IS DISTINCT FROM p->>'epoch' OR v_version>h.version THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control';END IF;
 IF v_version<h.version THEN RETURN jsonb_build_object('completed',true,'superseded',true);END IF;
 IF v_outcome NOT IN('applied','replay') OR h.digest IS DISTINCT FROM p->>'digest' OR h.kind IS DISTINCT FROM p->>'kind' THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: invalid control';END IF;
 UPDATE sessions.ingest_source_control_heads SET pending=false,updated_at=clock_timestamp()
  WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user;
 RETURN jsonb_build_object('completed',true,'superseded',false);
END $control_complete$;

-- ---------------------------------------------------------------------------------------------------------------
-- The transcript eraser's least-privilege read surface (zero-Neon E3; independent dogpatch review P0/P1).
--
-- P0: under the Supabase authority, what a user deleted is the UNION of
--   * sessions.ingest_frozen_source_deletions: Neon-era sessions, kept exactly as Neon kept deleted_upload_sessions;
--   * sessions.upload_deletions: the target's own fences, written by the ordered fence for EVERY session (Neon-era
--     and post-cutover uploads alike) on a disable or reset.
-- A post-cutover session exists only in the second, so the eraser reads the deduplicated union.
--
-- P1: the eraser connects as bulls96_privacy_eraser (provisioned NOLOGIN by supabase/bootstrap/session_ingest_roles.sql,
-- made LOGIN only by the operator phase privacy_eraser_role.sql). It holds EXECUTE on exactly these four SECURITY
-- DEFINER functions and no table, column or sequence right (privacy_eraser_verify.sql), so the host that holds the
-- destructive S3 key holds no owner or BYPASSRLS database credential. Every read refuses unless the authority is active.
DO $eraser_role$
DECLARE r pg_roles%ROWTYPE;
BEGIN
 SELECT * INTO r FROM pg_roles WHERE rolname='bulls96_privacy_eraser';
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42704',MESSAGE='role bulls96_privacy_eraser does not exist; this migration does not create it',
  HINT='Run supabase/bootstrap/session_ingest_roles.sql (or cloudsql_migration_roles.sql) first, then rerun.';END IF;
 IF r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication OR r.rolinherit THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='role bulls96_privacy_eraser exists elevated';END IF;
END $eraser_role$;

CREATE FUNCTION sessions.ingest_privacy_eraser_state() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $eraser_state$
 SELECT jsonb_build_object('active',EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority WHERE state='active'))
$eraser_state$;

CREATE FUNCTION sessions.ingest_privacy_eraser_require_active() RETURNS void
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,sessions,pg_temp AS $eraser_require$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM sessions.ingest_privacy_authority WHERE state='active') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='frozen source: supabase privacy authority not active';END IF;
END $eraser_require$;

-- Every exported (org, session) group a deletion fence covers, bounded (overflow refuses the sweep, as on Neon).
CREATE FUNCTION sessions.ingest_privacy_eraser_groups() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $eraser_groups$
DECLARE v jsonb;n bigint;
BEGIN
 PERFORM sessions.ingest_privacy_eraser_require_active();
 SELECT coalesce(jsonb_agg(jsonb_build_object('org_id',org_id,'session_id',session_id)),'[]'::jsonb),count(*) INTO v,n FROM(
  SELECT org_id,session_id FROM sessions.ingest_frozen_source_deletions
  UNION SELECT org_id,session_id FROM sessions.upload_deletions LIMIT 100001)g;
 IF n>100000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='frozen source: too many fenced groups';END IF;
 RETURN v;
END $eraser_groups$;

-- One keyset page of the deduplicated union of fenced (org, ws, user, origin, source, session), in C order.
-- p: {"after": null | [org, ws, user, origin, source, session], "limit": 1..5000}
CREATE FUNCTION sessions.ingest_privacy_eraser_page(p jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $eraser_page$
DECLARE v_limit int;a jsonb;v jsonb;
BEGIN
 PERFORM sessions.ingest_exact_keys(p,ARRAY['after','limit']);
 IF jsonb_typeof(p->'limit') IS DISTINCT FROM 'number' OR p->>'limit'!~'^[1-9][0-9]{0,3}$' OR (p->>'limit')::int>5000 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid eraser page limit';END IF;
 v_limit:=(p->>'limit')::int;a:=p->'after';
 IF a<>'null'::jsonb AND (jsonb_typeof(a)<>'array' OR jsonb_array_length(a)<>6
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(a) e WHERE jsonb_typeof(e)<>'string')) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid eraser page cursor';END IF;
 PERFORM sessions.ingest_privacy_eraser_require_active();
 SELECT coalesce(jsonb_agg(jsonb_build_object('org_id',org_id,'workspace_id',workspace_id,'user_id',user_id,'origin_id',origin_id,
   'source',source,'session_id',session_id) ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",
   origin_id COLLATE "C",source COLLATE "C",session_id COLLATE "C"),'[]'::jsonb) INTO v FROM(
  SELECT * FROM(
   SELECT org_id,workspace_id,user_id,origin_id,source,session_id FROM sessions.ingest_frozen_source_deletions
   UNION SELECT org_id,workspace_id,user_id,origin_id,source,session_id FROM sessions.upload_deletions)u
  WHERE a='null'::jsonb OR (org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",origin_id COLLATE "C",source COLLATE "C",session_id COLLATE "C")
   > (a->>0,a->>1,a->>2,a->>3,a->>4,a->>5)
  ORDER BY org_id COLLATE "C",workspace_id COLLATE "C",user_id COLLATE "C",origin_id COLLATE "C",source COLLATE "C",session_id COLLATE "C"
  LIMIT v_limit)q;
 RETURN v;
END $eraser_page$;

-- Re-read right before an erasure: still fenced in either set (a re-enable removes the row from both).
CREATE FUNCTION sessions.ingest_privacy_eraser_still_fenced(p jsonb) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,sessions,pg_temp AS $eraser_still$
DECLARE g text[];
BEGIN
 PERFORM sessions.ingest_exact_keys(p,ARRAY['org_id','workspace_id','user_id','origin_id','source','session_id']);
 IF EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE jsonb_typeof(e.value)<>'string') THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='frozen source: invalid eraser group';END IF;
 PERFORM sessions.ingest_privacy_eraser_require_active();
 g:=ARRAY[p->>'org_id',p->>'workspace_id',p->>'user_id',p->>'origin_id',p->>'source',p->>'session_id'];
 RETURN EXISTS(SELECT 1 FROM sessions.ingest_frozen_source_deletions WHERE org_id=g[1] AND workspace_id=g[2] AND user_id=g[3]
   AND origin_id=g[4] AND source=g[5] AND session_id=g[6])
  OR EXISTS(SELECT 1 FROM sessions.upload_deletions WHERE org_id=g[1] AND workspace_id=g[2] AND user_id=g[3]
   AND origin_id=g[4] AND source=g[5] AND session_id=g[6]);
END $eraser_still$;

REVOKE ALL ON FUNCTION sessions.ingest_privacy_eraser_state(),sessions.ingest_privacy_eraser_require_active(),
 sessions.ingest_privacy_eraser_groups(),sessions.ingest_privacy_eraser_page(jsonb),sessions.ingest_privacy_eraser_still_fenced(jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder;
GRANT USAGE ON SCHEMA sessions TO bulls96_privacy_eraser;
GRANT EXECUTE ON FUNCTION sessions.ingest_privacy_eraser_state(),sessions.ingest_privacy_eraser_groups(),
 sessions.ingest_privacy_eraser_page(jsonb),sessions.ingest_privacy_eraser_still_fenced(jsonb) TO bulls96_privacy_eraser;

-- Lazy-current adoption: the source-side exclusion of 20261105040000 becomes an EXACT list (lead ruling 2026-11-07,
-- c3-041-exact-source-exclusions). 040000 excluded the whole ingest_frozen_source_ prefix, which would silently admit a
-- future TARGET-side table sharing it. Both bodies are 040000's verbatim except that predicate and its comment. The
-- list is 010000's six frozen-copy tables, plus ingest_frozen_source_owned_sessions (created above; the Neon owned-set
-- copy, written only by sync-owned/the authority apply, read through the authority), plus ingest_source_control_heads.
-- The rollback restores the exact 040000 bodies.
CREATE OR REPLACE FUNCTION sessions.ingest_lazy_user(p_w jsonb,p_kind text,p_control jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $lazy_user$
DECLARE v_org text;v_ws text;v_user text;v_epoch text;v_source text;v_first boolean;v_last bigint;v_version bigint;v_privacy_version bigint;
 s sessions.ingest_lazy_user_seals%ROWTYPE;b sessions.ingest_seed_fence_baselines%ROWTYPE;v_privacy jsonb;v_d jsonb;v_r jsonb;v_fp text;k record;v_exists boolean;
BEGIN
 v_org:=sessions.ingest_identifier(p_w#>'{tenant,orgId}',false);v_ws:=sessions.ingest_identifier(p_w#>'{tenant,workspaceId}',true);
 v_user:=sessions.ingest_identifier(p_w#>'{tenant,userId}',false);v_epoch:=sessions.ingest_digest(p_w->'controlEpoch');
 v_source:=sessions.ingest_digest(p_w->'sourceIdentitySha256');
 IF jsonb_typeof(p_w->'sourceControlVersion') IS DISTINCT FROM 'string' OR p_w->>'sourceControlVersion'!~'^(0|[1-9][0-9]{0,18})$'
  OR jsonb_typeof(p_w->'privacyVersion') IS DISTINCT FROM 'string' OR p_w->>'privacyVersion'!~'^(0|[1-9][0-9]{0,18})$' THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: witness version shape';END IF;
 v_version:=(p_w->>'sourceControlVersion')::bigint;v_privacy_version:=(p_w->>'privacyVersion')::bigint;
 INSERT INTO sessions.ingest_fence_owners VALUES(v_org,v_ws,v_user) ON CONFLICT DO NOTHING RETURNING true INTO v_first;
 PERFORM sessions.ingest_lock_fences(v_org,v_ws,v_user);
 SELECT coalesce(max(version),0) INTO v_last FROM sessions.ingest_control_receipts
  WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user AND epoch=v_epoch;
 IF p_kind='batch' THEN
  IF p_w->'pending' IS DISTINCT FROM 'false'::jsonb OR p_w->'pendingControl' IS DISTINCT FROM 'null'::jsonb
   OR v_version<>v_last OR v_privacy_version<>v_version THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source control version changed';END IF;
 ELSE
  IF p_w->'pending' IS DISTINCT FROM 'true'::jsonb OR p_w->'pendingControl' IS DISTINCT FROM p_control
   OR p_control->>'epoch' IS DISTINCT FROM v_epoch OR p_control->>'kind' IS DISTINCT FROM p_kind
   OR p_control->>'version' IS DISTINCT FROM v_version::text OR v_version=0 OR v_privacy_version<>v_version-1 THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: pending source control mismatch';END IF;
  IF v_last<v_version THEN
   IF v_last=9223372036854775807 OR v_last+1<>v_version THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source control gap';END IF;
  ELSE
   PERFORM 1 FROM sessions.ingest_control_receipts WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user
    AND epoch=v_epoch AND version=v_version AND kind=p_kind AND digest=p_control->>'digest';
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source control replay mismatch';END IF;
  END IF;
 END IF;
 SELECT * INTO s FROM sessions.ingest_lazy_user_seals WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user;
 IF FOUND THEN
  SELECT * INTO b FROM sessions.ingest_seed_fence_baselines WHERE org_id=v_org AND workspace_id=v_ws AND user_id=v_user;
  IF NOT FOUND OR s.source_identity_sha256<>v_source OR s.control_epoch<>v_epoch OR s.privacy_fingerprint<>b.fingerprint THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: existing user privacy authority changed';END IF;
  RETURN jsonb_build_object('privacySealed',true,'created',false,'targetVersion',v_last::text);
 END IF;
 -- An already-completed source control implies a previously sealed target.
 -- Lost authority cannot silently become a fresh user merely because rows vanished.
 IF v_first IS DISTINCT FROM true OR v_last<>0 OR v_privacy_version<>0 THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: unsealed user authority cannot be adopted';END IF;
 FOR k IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='sessions' AND c.relkind='r' AND (c.relname LIKE 'ingest_%' OR c.relname LIKE 'upload_%')
   AND c.relname<>'ingest_fence_owners'
   -- Source-side state is not prior TARGET authority: EXACTLY the six 010000 frozen-copy tables, 041000's owned-set
   -- copy and the Supabase-first control heads. Any other ingest_/upload_ table (even one sharing the prefix) is checked.
   AND c.relname NOT IN('ingest_frozen_source_records','ingest_frozen_source_deletions','ingest_frozen_source_resets',
    'ingest_frozen_source_org_seals','ingest_frozen_source_completeness','ingest_frozen_source_receipts',
    'ingest_frozen_source_owned_sessions') AND c.relname<>'ingest_source_control_heads'
   AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['org_id','workspace_id','user_id']) col
    WHERE NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attname=col AND a.attnum>0 AND NOT a.attisdropped))
 LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM sessions.%I WHERE org_id=$1 AND workspace_id=$2 AND user_id=$3)',k.relname)
   INTO v_exists USING v_org,v_ws,v_user;
  IF v_exists THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: prior user authority requires reviewed recovery';END IF;
 END LOOP;
 v_privacy:=p_w->'privacy';
 PERFORM sessions.ingest_exact_keys(v_privacy,ARRAY['complete','deletions','resets']);
 IF v_privacy->'complete' IS DISTINCT FROM 'true'::jsonb OR octet_length(v_privacy::text)>524288
  OR jsonb_typeof(v_privacy->'deletions') IS DISTINCT FROM 'array' OR jsonb_typeof(v_privacy->'resets') IS DISTINCT FROM 'array'
  OR jsonb_array_length(v_privacy->'deletions')+jsonb_array_length(v_privacy->'resets')>5000 THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: complete bounded cold privacy required';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_privacy->'deletions') q(e) WHERE CASE WHEN jsonb_typeof(e)<>'object' THEN true ELSE
  ARRAY(SELECT x FROM jsonb_object_keys(e)x ORDER BY x COLLATE "C") IS DISTINCT FROM ARRAY['origin_id','session_id','source']::text[] END)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_privacy->'resets')q(e) WHERE CASE WHEN jsonb_typeof(e)<>'object' THEN true ELSE
  ARRAY(SELECT x FROM jsonb_object_keys(e)x ORDER BY x COLLATE "C") IS DISTINCT FROM ARRAY['deleted','request_id']::text[]
  OR jsonb_typeof(e->'deleted') IS DISTINCT FROM 'string' OR e->>'deleted'!~'^(0|[1-9][0-9]{0,18})$' END)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid cold privacy metadata';END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text COLLATE "C"),'[]') INTO v_d FROM(
  SELECT DISTINCT jsonb_build_object('origin_id',sessions.ingest_identifier(e->'origin_id',false),
   'source',sessions.ingest_identifier(e->'source',false),'session_id',sessions.ingest_identifier(e->'session_id',false)) x
  FROM jsonb_array_elements(v_privacy->'deletions')q(e))q;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text COLLATE "C"),'[]') INTO v_r FROM(
  SELECT DISTINCT jsonb_build_object('request_id',sessions.ingest_identifier(e->'request_id',false),'deleted',(e->>'deleted')::bigint) x
  FROM jsonb_array_elements(v_privacy->'resets')q(e))q;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_r)x GROUP BY x->>'request_id' HAVING count(*)>1) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: conflicting reset metadata';END IF;
 v_fp:=encode(sha256(convert_to(jsonb_build_array('neon-fence-baseline-v1',v_org,v_ws,v_user,v_d,v_r)::text,'UTF8')),'hex');
 INSERT INTO sessions.ingest_fence_versions(org_id,workspace_id,user_id,origin_id,source,session_id,epoch)
  SELECT v_org,v_ws,v_user,x.origin_id,x.source,x.session_id,1 FROM jsonb_to_recordset(v_d)x(origin_id text,source text,session_id text);
 INSERT INTO sessions.upload_deletions(org_id,workspace_id,user_id,origin_id,source,session_id)
  SELECT v_org,v_ws,v_user,x.origin_id,x.source,x.session_id FROM jsonb_to_recordset(v_d)x(origin_id text,source text,session_id text);
 INSERT INTO sessions.upload_resets(org_id,workspace_id,user_id,request_id,deleted)
  SELECT v_org,v_ws,v_user,x.request_id,x.deleted FROM jsonb_to_recordset(v_r)x(request_id text,deleted bigint);
 INSERT INTO sessions.ingest_seed_fence_baselines(org_id,workspace_id,user_id,fingerprint,imported_at)
  VALUES(v_org,v_ws,v_user,v_fp,clock_timestamp());
 INSERT INTO sessions.ingest_lazy_user_seals(org_id,workspace_id,user_id,source_identity_sha256,control_epoch,privacy_fingerprint,initial_privacy_version)
  VALUES(v_org,v_ws,v_user,v_source,v_epoch,v_fp,v_privacy_version);
 RETURN jsonb_build_object('privacySealed',true,'created',true,'targetVersion',v_last::text);
END $lazy_user$;

CREATE OR REPLACE FUNCTION sessions.ingest_lazy_begin(p jsonb,p_kind text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $lazy_begin$
DECLARE pol sessions.ingest_lazy_policy%ROWTYPE;c sessions.ingest_receipt_seat_clock%ROWTYPE;
 v_gen text;v_packet jsonb;w jsonb;v_org text;v_ws text;v_user text;v_new boolean;v_exists boolean;k record;
 v_records jsonb;v_count integer;v_seen integer;v_ack jsonb;
BEGIN
 IF p_kind NOT IN('batch','selection','reset') OR p_kind IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid witness operation';END IF;
 v_gen:=sessions.ingest_digest(p->'generation');PERFORM sessions.ingest_require_generation(v_gen);
 SELECT * INTO STRICT pol FROM sessions.ingest_lazy_policy WHERE singleton FOR SHARE;
 SELECT * INTO STRICT c FROM sessions.ingest_receipt_seat_clock WHERE singleton;
 IF pol.generation<>v_gen OR pol.valid_until<=clock_timestamp() OR pol.source_identity_sha256<>c.source_identity_sha256
  OR pol.control_epoch<>c.control_epoch OR pol.source_proof_sha256 IS DISTINCT FROM c.baseline->>'sourceProofSha256' THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: current custody policy unavailable';END IF;
 v_packet:=p->'custody';PERFORM sessions.ingest_exact_keys(v_packet,ARRAY['witness','sourceDigest']);w:=v_packet->'witness';
 PERFORM sessions.ingest_exact_keys(w,ARRAY['version','issuer','sourceIdentitySha256','controlEpoch','privacyBaselineSha256',
  'tenant','originId','batchId','batchDigest','sourceControlVersion','pending','pendingControl','privacyVersion',
  'originalRecordCount','candidateCount','records','privacy']);
 IF encode(sha256(convert_to(w::text,'UTF8')),'hex')<>sessions.ingest_digest(v_packet->'sourceDigest')
  OR w->'version' IS DISTINCT FROM '1'::jsonb OR w->>'issuer' IS DISTINCT FROM pol.issuer
  OR w->>'sourceIdentitySha256' IS DISTINCT FROM pol.source_identity_sha256 OR w->>'controlEpoch' IS DISTINCT FROM pol.control_epoch
  OR w->>'privacyBaselineSha256' IS DISTINCT FROM pol.privacy_baseline_sha256 OR w->'tenant' IS DISTINCT FROM p->'tenant' THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source witness identity mismatch';END IF;
 PERFORM sessions.ingest_exact_keys(p->'tenant',ARRAY['orgId','workspaceId','userId']);
 v_org:=sessions.ingest_identifier(p#>'{tenant,orgId}',false);v_ws:=sessions.ingest_identifier(p#>'{tenant,workspaceId}',true);
 v_user:=sessions.ingest_identifier(p#>'{tenant,userId}',false);
 IF jsonb_typeof(w->'records') IS DISTINCT FROM 'array' OR octet_length((w->'records')::text)>4194304
  OR jsonb_typeof(w->'candidateCount') IS DISTINCT FROM 'number' OR w->>'candidateCount'!~'^(0|[1-9][0-9]{0,2})$'
  OR jsonb_typeof(w->'originalRecordCount') IS DISTINCT FROM 'number' OR w->>'originalRecordCount'!~'^(0|[1-9][0-9]{0,2})$'
  OR (w->>'candidateCount')::integer>500 OR (w->>'originalRecordCount')::integer>500
  OR (w->>'candidateCount')::integer>(w->>'originalRecordCount')::integer
  OR jsonb_array_length(w->'records')<>(w->>'candidateCount')::integer THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: source witness record bound';END IF;
 IF p_kind='batch' THEN
  v_records:=sessions.ingest_records(p->'records');v_count:=jsonb_array_length(v_records);
  IF w->>'originId' IS DISTINCT FROM p->>'originId' OR w->>'batchId' IS DISTINCT FROM p->>'batchId'
   OR w->>'batchDigest' IS DISTINCT FROM p->>'batchDigest' OR v_count<>(w->>'candidateCount')::integer THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source witness batch mismatch';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(w->'records')q(e) WHERE CASE WHEN jsonb_typeof(e)<>'object' THEN true ELSE
   ARRAY(SELECT x FROM jsonb_object_keys(e)x ORDER BY x COLLATE "C") IS DISTINCT FROM
    ARRAY['candidateDigest','candidateFenced','current','currentFenced','preparedOrd','processingRank','recordId','revision','revisionId']::text[]
   OR jsonb_typeof(e->'preparedOrd') IS DISTINCT FROM 'number' OR e->>'preparedOrd'!~'^(0|[1-9][0-9]{0,2})$'
   OR jsonb_typeof(e->'processingRank') IS DISTINCT FROM 'number' OR e->>'processingRank'!~'^(0|[1-9][0-9]{0,2})$'
   OR jsonb_typeof(e->'candidateFenced') IS DISTINCT FROM 'boolean' OR jsonb_typeof(e->'currentFenced') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(e->'current') NOT IN('object','null') END)
  THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: source witness record shape';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(w->'records')q(e)
   WHERE (e->>'preparedOrd')::integer>=v_count OR (e->>'processingRank')::integer>=v_count)
   OR (SELECT count(DISTINCT e->>'preparedOrd') FROM jsonb_array_elements(w->'records')q(e))<>v_count
   OR (SELECT count(DISTINCT e->>'processingRank') FROM jsonb_array_elements(w->'records')q(e))<>v_count THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source witness rank coverage';END IF;
  SELECT count(*)::integer INTO v_seen FROM jsonb_array_elements(w->'records')q(e)
   JOIN jsonb_to_recordset(v_records)r(ord integer,record_id text,revision bigint,revision_id text,digest text,session_id text)
   ON r.ord=(e->>'preparedOrd')::integer AND r.record_id=e->>'recordId' AND r.revision::text=e->>'revision'
    AND r.revision_id=e->>'revisionId' AND r.digest=e->>'candidateDigest'
   WHERE NOT((e->>'candidateFenced')::boolean AND r.session_id IS NULL);
  IF v_seen<>v_count THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source candidate metadata mismatch';END IF;
 ELSE
  IF w->'batchId' IS DISTINCT FROM 'null'::jsonb OR w->'batchDigest' IS DISTINCT FROM 'null'::jsonb
   OR w->'originalRecordCount' IS DISTINCT FROM '0'::jsonb OR w->'candidateCount' IS DISTINCT FROM '0'::jsonb
   OR w->'records' IS DISTINCT FROM '[]'::jsonb
   OR (p_kind='reset' AND w->'originId' IS DISTINCT FROM 'null'::jsonb)
   OR (p_kind='selection' AND w->>'originId' IS DISTINCT FROM p->>'originId') THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: source control witness shape';END IF;
 END IF;
 -- The trusted source context permits provisioning, not a claim of empty org
 -- history. Retained closed admissions are never reopened by a runtime request.
 INSERT INTO sessions.ingest_buffer_admission(org_id,privacy_baseline_sha256,retention_contract_sha256,schema_generation,valid_until,control_epoch)
 VALUES(v_org,pol.privacy_baseline_sha256,pol.retention_contract_sha256,v_gen,pol.valid_until,pol.control_epoch)
 ON CONFLICT DO NOTHING RETURNING true INTO v_new;
 PERFORM 1 FROM sessions.ingest_buffer_admission WHERE org_id=v_org AND privacy_baseline_sha256=pol.privacy_baseline_sha256
  AND retention_contract_sha256=pol.retention_contract_sha256 AND schema_generation=v_gen AND control_epoch=pol.control_epoch
  AND valid_until>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: retained org admission closed or conflicting';END IF;
 IF v_new IS TRUE THEN
  FOR k IN SELECT t.relname FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace
   WHERE n.nspname='sessions' AND t.relkind='r' AND(t.relname LIKE 'ingest_%' OR t.relname LIKE 'upload_%')
    AND t.relname<>'ingest_buffer_admission'
    -- Source-side state is not prior TARGET authority: EXACTLY the six 010000 frozen-copy tables, 041000's owned-set
    -- copy and the Supabase-first control heads. Any other ingest_/upload_ table (even one sharing the prefix) is checked.
    AND t.relname NOT IN('ingest_frozen_source_records','ingest_frozen_source_deletions','ingest_frozen_source_resets',
     'ingest_frozen_source_org_seals','ingest_frozen_source_completeness','ingest_frozen_source_receipts',
     'ingest_frozen_source_owned_sessions') AND t.relname<>'ingest_source_control_heads'
    AND EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=t.oid AND a.attname='org_id' AND a.attnum>0 AND NOT a.attisdropped)
  LOOP
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM sessions.%I WHERE org_id=$1)',k.relname) INTO v_exists USING v_org;
   IF v_exists THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: unbound prior org authority requires recovery';END IF;
  END LOOP;
 END IF;
 v_ack:=sessions.ingest_lazy_user(w,p_kind,p->'control');
 PERFORM sessions.ingest_require_generation(v_gen);
 IF pol.valid_until<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: policy expired during operation';END IF;
 RETURN v_ack;
END $lazy_begin$;
